// The skall tuvali's six reaction faces (docs/design/sistem/uretec/veri/emotes.json), each in a
// round →
// apps/mobile/src/theme/emotes.generated.ts: each face's SVG, keyed like the server's reactions
// (supabase/functions/_shared/pure/reactions.ts). `node --experimental-strip-types
// scripts/sistem/emotes.ts`; the test (emotes.test.ts) checks the generated file against the canvas.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { REACTIONS } from '../../supabase/functions/_shared/pure/reactions.ts';

// Each face in a round (the owner's call, 30 Ekim: the buddies did not read at the size of a
// reaction; nothing over them, no clouds or sparks): the capsule's head and face, larger, in a
// circle of its own colour's light tint. The capsule and its face are the canvas's; the
// decorations around them are left out.
const SCALE = 1.4;
const TINT = 0.78;

function tint(hex: string, amount: number): string {
  const n = parseInt(hex.slice(1), 16);
  const mix = (c: number) => Math.round(c + (255 - c) * amount);
  const rgb = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map(mix);
  return `#${rgb.map((c) => c.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
}

export function emotesSource(root: string): string {
  const all = JSON.parse(
    readFileSync(join(root, 'docs/design/sistem/uretec/veri/emotes.json'), 'utf8'),
  ) as Record<string, { svg: string }>;
  const entries = REACTIONS.map((key) => {
    const svg = all[key]?.svg;
    if (!svg) throw new Error(`emotes.json: no ${key}`);
    // The capsule and its face: the clipped group's one inner group.
    const open = '<g clip-path="url(#__ID__)">';
    const at = svg.indexOf(open);
    if (at < 0) throw new Error(`emotes.json: ${key} has another clip`);
    const rest = svg.slice(at + open.length);
    const close = rest.indexOf('</g></g>');
    if (close < 0 || !rest.startsWith('<g>')) throw new Error(`emotes.json: ${key} has another face`);
    const face = rest.slice(0, close + '</g>'.length);
    const body = /<rect x="10" y="8" width="28" height="56" rx="14" fill="(#[0-9A-Fa-f]{6})"/.exec(
      face,
    )?.[1];
    if (!body) throw new Error(`emotes.json: ${key} has another capsule`);
    const id = `em-${key}`;
    const drawing =
      `<svg viewBox="0 0 48 48"><defs><clipPath id="${id}"><circle cx="24" cy="24" r="24"/></clipPath></defs>` +
      `<g clip-path="url(#${id})"><circle cx="24" cy="24" r="24" fill="${tint(body, TINT)}"/>` +
      `<g transform="translate(24 24) scale(${SCALE}) translate(-24 -20)">${face}</g></g></svg>`;
    return `  ${key}: ${JSON.stringify(drawing)},`;
  });
  return `// Generated by scripts/sistem/emotes.ts from the skall tuvali (docs/design/sistem/uretec). Do not\n// edit; run the script.\nexport const EMOTES = {\n${entries.join('\n')}\n} as const;\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, 'apps/mobile/src/theme/emotes.generated.ts'), emotesSource(root));
}
